mkdir -p /tmp/rf; cat > /tmp/rf/flatten.pl <<'EOF'
use strict; use warnings;
my @files = split /\n/, `find spec -name '*.pi'`;
my (%blocks, %kind, %fileof);
my %data;
for my $f (@files) {
  open my $fh, '<', $f or die; my @l = <$fh>; close $fh;
  my @bl; my $cur;
  for my $line (@l) {
    if ($line =~ /^\S/) { $cur = { lines => [$line] }; push @bl, $cur;
      if ($line =~ /^(export )?(abstract )?([a-z][a-z-]*) ([A-Z]\w*)\b(.*):\s*$/) { $cur->{kw}=$3; $cur->{name}=$4; $cur->{exp}=$1?1:0; }
    } else { if (!$cur) { $cur = { lines => [] }; push @bl, $cur; } push @{$cur->{lines}}, $line; }
  }
  $data{$f} = \@bl;
  for my $b (@bl) { next unless $b->{name}; $kind{$b->{name}} = $b->{kw}; $blocks{$b->{name}} = $b; $fileof{$b->{name}} = $f; }
}
my %owner; my %inlined;
sub body { my $b = shift; my @l = @{$b->{lines}}; shift @l; return @l; }
sub expand_shape {
  my ($s) = @_; my @out;
  for my $ln (body($blocks{$s})) { push @out, $ln; }
  return @out;
}
for my $f (@files) {
  for my $b (@{$data{$f}}) {
    next unless $b->{name} && ($kind{$b->{name}}//'') ne 'concept' && ($kind{$b->{name}}//'') ne 'shape';
    my @new; my $changed = 0;
    for my $ln (@{$b->{lines}}) {
      if ($ln =~ /^    concept: \{(\w+)\}\s*$/ && ($kind{$1}//'') eq 'concept') {
        my $c = $1; $owner{$c} = $b->{name}; $inlined{$c} = 1; $changed = 1;
        my @cb = body($blocks{$c});
        # strip trailing blank lines of concept body
        for my $cl (@cb) {
          if ($cl =~ /^    shape: \{(\w+)\}\s*$/ && ($kind{$1}//'') eq 'shape') {
            my $s = $1; $owner{$s} = $b->{name}; $inlined{$s} = 1;
            my @sb = body($blocks{$s}); push @new, @sb;
          } else { push @new, $cl; }
        }
      } else { push @new, $ln; }
    }
    $b->{lines} = \@new if $changed;
  }
}
for my $f (@files) {
  my @out;
  for my $b (@{$data{$f}}) {
    if ($b->{name} && $inlined{$b->{name}}) { next; }
    my $t = join '', @{$b->{lines}};
    if ($b->{name} && ($kind{$b->{name}}//'') eq 'shape') { $t =~ s/^(export )?shape /$1anchor /; }
    if ($b->{name} && ($kind{$b->{name}}//'') eq 'scope') { $t =~ s/^(export )?scope /$1feature /; }
    push @out, $t;
  }
  my $t = join '', @out;
  for my $n (keys %owner) { my $o = $owner{$n}; $t =~ s/\b$n\.(\w)/$o.$1/g; }
  $t =~ s/\n{3,}/\n\n/g;
  open my $fh, '>', $f or die; print $fh $t; close $fh;
}
print scalar(keys %inlined), " inlined\n";
for my $n (sort keys %kind) { next unless $kind{$n} =~ /^(concept|shape)$/; next if $inlined{$n}; print "kept $kind{$n} $n ($fileof{$n})\n"; }
EOF
cd /home/hyphyphyph/piton/repl; perl /tmp/rf/flatten.pl 2>&1 | tail -40

